    "Exports the current local request log as JSON. URLs may contain query parameters.": "Експортира текущия локален дневник на заявките като JSON. URL адресите може да съдържат параметри на заявката.",
    "Export a backup first if you want to keep a copy.": "Първо експортирайте резервно копие, ако искате да запазите копие.",
    "If a tab renderer crashes, Murky automatically restores that tab instead of leaving it blank.": "Ако визуализаторът на раздел се срине, Murky автоматично възстановява раздела, вместо да го оставя празен.",
    "Enabled": "Включено",
    "Microphone/camera access is denied to external websites. Murky's own voice features retain access.": "Достъпът до микрофона/камерата е отказан за външни уебсайтове. Собствените гласови функции на Murky запазват достъпа.",
    "Restricted": "Ограничено",
    "Blocks network requests from external websites. Murky internal pages and local features continue to work.": "Блокира мрежовите заявки от външни уебсайтове. Вътрешните страници и локалните функции на Murky продължават да работят.",
    "Saves a local backup of your settings, history and bookmarks before a purge.": "Запазва локално резервно копие на настройките, историята и отметките ви преди изчистване.",
    "Clears browsing history, bookmarks, cookies, local storage, service workers and cached web data in one action.": "Изчиства историята на сърфирането, отметките, бисквитките, локалното хранилище, service worker-ите и кешираните уеб данни с едно действие.",
    "Version …": "Версия …",
    "Restores every Murky setting to its default value": "Възстановява всички настройки на Murky до стойностите им по подразбиране",
    "The only official Murky websites are": "Единствените официални уебсайтове на Murky са",
    "and": "и",
    ". Be careful with websites claiming to be Murky.": ". Внимавайте с уебсайтове, които твърдят, че са Murky.",
    "Use an image as Murky's background.": "Използвайте изображение като фон на Murky.",
