    "Back online. Reconnecting…": "Отново сте онлайн. Свързване…",
    "Murky blocked this page to protect you. If you understand the risk, you can open it anyway. Anything you send to {site} may be visible to others.": "Murky блокира тази страница, за да ви защити. Ако разбирате риска, можете да я отворите въпреки това. Всичко, което изпращате към {site}, може да бъде видимо за други.",
    "Press space or click to play": "Натиснете интервал или щракнете, за да играете",
    "Game over. Press space or click to retry": "Край на играта. Натиснете интервал или щракнете, за да опитате пак",
    "this site": "този сайт",
    "Page not found": "Страницата не е намерена",
    "There's nothing at this address. It may have moved or been deleted.": "На този адрес няма нищо. Може да е преместена или изтрита.",
    "Access denied": "Достъпът е отказан",
    "You don't have permission to view this page. You may need to sign in.": "Нямате разрешение да видите тази страница. Може да се наложи да влезете в профила си.",
    "Too many requests": "Твърде много заявки",
    "This site is asking you to slow down. Wait a bit and try again.": "Този сайт ви моли да забавите. Изчакайте малко и опитайте отново.",
    "Server error": "Грешка в сървъра",
    "Something went wrong on the site's end. Try again in a moment.": "От страна на сайта нещо се обърка. Опитайте отново след малко.",
    "Couldn't open this page": "Страницата не може да се отвори",
    "The site refused to show this page.": "Сайтът отказа да покаже тази страница.",
    "You're offline": "Няма връзка с интернет",
    "Murky can't reach the internet. Check your connection and we'll reconnect when you're back.": "Murky няма достъп до интернет. Проверете връзката си и ще се свържем отново, щом се върнете.",
    "Can't find this site": "Сайтът не е намерен",
    "Murky couldn't find a server called {site}. Check the address for typos.": "Murky не намери сървър с име {site}. Проверете адреса за правописни грешки.",
    "{site} refused to connect": "{site} отказа връзката",
    "The site might be down. Try again in a moment.": "Сайтът може да не работи. Опитайте отново след малко.",
    "Took too long to respond": "Отговорът отне твърде дълго",
    "{site} didn't answer in time. Try again in a moment.": "{site} не отговори навреме. Опитайте отново след малко.",
    "Connection interrupted": "Връзката е прекъсната",
    "The connection to {site} was dropped before the page finished loading.": "Връзката с {site} прекъсна, преди страницата да се зареди напълно.",
    "This site isn't safe to open": "Този сайт не е безопасен",
    "Murky couldn't verify that this site's connection is secure, so it blocked the page.": "Murky не можа да потвърди, че връзката с този сайт е защитена, затова блокира страницата.",
    "The site's security certificate was issued for a different address.": "Сертификатът за сигурност на сайта е издаден за друг адрес.",
    "The site's security certificate has expired or isn't valid yet. Check your device's date and time.": "Сертификатът за сигурност на сайта е изтекъл или още не е валиден. Проверете датата и часа на устройството си.",
    "The site's certificate was issued by an authority Murky doesn't trust.": "Сертификатът на сайта е издаден от орган, на който Murky не се доверява.",
    "Blocked by Murky": "Блокирано от Murky",
    "{site} was blocked by your ad and tracker protection.": "{site} е блокиран от защитата ви срещу реклами и тракери.",
    "Too many redirects": "Твърде много пренасочвания",
    "{site} keeps sending Murky in circles. Clearing its cookies often helps.": "{site} върти Murky в кръг. Често помага изчистването на бисквитките му.",
    "That address doesn't look right": "Адресът изглежда неправилен",
    "Murky can't open this address. Check it for typos.": "Murky не може да отвори този адрес. Проверете го за правописни грешки.",
    "Proxy problem": "Проблем с прокси",
    "Murky couldn't connect through your proxy server.": "Murky не успя да се свърже през вашия прокси сървър.",
    "File not found": "Файлът не е намерен",
    "That file doesn't exist or can't be opened.": "Този файл не съществува или не може да бъде отворен.",
    "Something went wrong": "Нещо се обърка",
    "Murky couldn't load {site}. Try again in a moment.": "Murky не успя да зареди {site}. Опитайте отново след малко."
