    "Too many requests": "Previše zahtjeva",
    "This site is asking you to slow down. Wait a bit and try again.": "Ovo web-mjesto traži da usporite. Pričekajte malo i pokušajte ponovno.",
    "Server error": "Pogreška poslužitelja",
    "Something went wrong on the site's end. Try again in a moment.": "Na strani web-mjesta nešto je pošlo po zlu. Pokušajte ponovno za trenutak.",
    "Couldn't open this page": "Nije moguće otvoriti ovu stranicu",
    "The site refused to show this page.": "Web-mjesto je odbilo prikazati ovu stranicu.",
    "You're offline": "Niste na mreži",
    "Murky can't reach the internet. Check your connection and we'll reconnect when you're back.": "Murky ne može doći do interneta. Provjerite vezu i ponovno ćemo se povezati čim se vratite.",
    "Can't find this site": "Nije moguće pronaći ovo web-mjesto",
    "Murky couldn't find a server called {site}. Check the address for typos.": "Murky nije pronašao poslužitelj s imenom {site}. Provjerite ima li u adresi tipfelera.",
    "{site} refused to connect": "{site} je odbio povezivanje",
    "The site might be down. Try again in a moment.": "Web-mjesto možda ne radi. Pokušajte ponovno za trenutak.",
    "Took too long to respond": "Odgovor je trajao predugo",
    "{site} didn't answer in time. Try again in a moment.": "{site} nije odgovorio na vrijeme. Pokušajte ponovno za trenutak.",
    "Connection interrupted": "Veza je prekinuta",
    "The connection to {site} was dropped before the page finished loading.": "Veza s {site} prekinuta je prije nego što se stranica učitala.",
    "This site isn't safe to open": "Ovo web-mjesto nije sigurno",
    "Murky couldn't verify that this site's connection is secure, so it blocked the page.": "Murky nije mogao potvrditi da je veza s ovim web-mjestom sigurna, pa je blokirao stranicu.",
    "The site's security certificate was issued for a different address.": "Sigurnosni certifikat web-mjesta izdan je za drugu adresu.",
    "The site's security certificate has expired or isn't valid yet. Check your device's date and time.": "Sigurnosni certifikat web-mjesta je istekao ili još nije valjan. Provjerite datum i vrijeme na uređaju.",
    "The site's certificate was issued by an authority Murky doesn't trust.": "Certifikat web-mjesta izdalo je tijelo kojem Murky ne vjeruje.",
    "Blocked by Murky": "Blokirao Murky",
    "{site} was blocked by your ad and tracker protection.": "{site} je blokirala vaša zaštita od oglasa i alata za praćenje.",
    "Too many redirects": "Previše preusmjeravanja",
    "{site} keeps sending Murky in circles. Clearing its cookies often helps.": "{site} vrti Murky u krug. Brisanje njegovih kolačića često pomaže.",
    "That address doesn't look right": "Ova adresa ne izgleda ispravno",
    "Murky can't open this address. Check it for typos.": "Murky ne može otvoriti ovu adresu. Provjerite ima li tipfelera.",
    "Proxy problem": "Problem s proxyjem",
    "Murky couldn't connect through your proxy server.": "Murky se nije mogao povezati preko vašeg proxy poslužitelja.",
    "File not found": "Datoteka nije pronađena",
    "That file doesn't exist or can't be opened.": "Ta datoteka ne postoji ili se ne može otvoriti.",
    "Something went wrong": "Nešto je pošlo po zlu",
    "Murky couldn't load {site}. Try again in a moment.": "Murky nije mogao učitati {site}. Pokušajte ponovno za trenutak."
