    "Not checked yet": "Még nincs ellenőrizve",
    "Murky keeps a rolling local log of browser network requests so you can inspect what leaves the browser.": "A Murky folyamatos helyi naplót vezet a böngésző hálózati kéréseiről, hogy ellenőrizhesd, mi hagyja el a böngészőt.",
    "Exports the current local request log as JSON. URLs may contain query parameters.": "Az aktuális helyi kérésnaplót JSON-ként exportálja. Az URL-ek lekérdezési paramétereket tartalmazhatnak.",
    "Export a backup first if you want to keep a copy.": "Ha meg szeretnél őrizni egy példányt, először exportálj biztonsági mentést.",
    "If a tab renderer crashes, Murky automatically restores that tab instead of leaving it blank.": "Ha egy lap renderelője összeomlik, a Murky automatikusan visszaállítja a lapot ahelyett, hogy üresen hagyná.",
    "Enabled": "Engedélyezve",
    "Microphone/camera access is denied to external websites. Murky's own voice features retain access.": "A külső webhelyek mikrofon- és kamerahozzáférése megtagadva. A Murky saját hangfunkciói továbbra is hozzáférnek.",
    "Restricted": "Korlátozott",
