    "Restricted": "Apribota",
    "Blocks network requests from external websites. Murky internal pages and local features continue to work.": "Blokuoja tinklo užklausas iš išorinių svetainių. Vidiniai Murky puslapiai ir vietinės funkcijos toliau veikia.",
    "Saves a local backup of your settings, history and bookmarks before a purge.": "Prieš valymą išsaugo vietinę nustatymų, istorijos ir žymių atsarginę kopiją.",
    "Clears browsing history, bookmarks, cookies, local storage, service workers and cached web data in one action.": "Vienu veiksmu išvalo naršymo istoriją, žymes, slapukus, vietinę saugyklą, service worker ir talpykloje esančius žiniatinklio duomenis.",
    "Version …": "Versija …",
