    "Blocked by Murky": "Užblokavo „Murky“",
    "{site} was blocked by your ad and tracker protection.": "{site} užblokavo jūsų reklamų ir sekimo priemonių apsauga.",
    "Too many redirects": "Per daug nukreipimų",
    "{site} keeps sending Murky in circles. Clearing its cookies often helps.": "{site} sukioja „Murky“ ratu. Dažnai padeda išvalyti jos slapukus.",
    "That address doesn't look right": "Šis adresas atrodo neteisingas",
    "Murky can't open this address. Check it for typos.": "„Murky“ negali atidaryti šio adreso. Patikrinkite, ar nėra rašybos klaidų.",
    "Proxy problem": "Tarpinio serverio problema",
