    "Murky keeps a rolling local log of browser network requests so you can inspect what leaves the browser.": "Murky یک گزارش محلی پیوسته از درخواست‌های شبکه مرورگر نگه می‌دارد تا بتوانید خروجی‌های مرورگر را بررسی کنید.",
    "Exports the current local request log as JSON. URLs may contain query parameters.": "گزارش محلی فعلی درخواست‌ها را به صورت JSON صادر می‌کند. URLها ممکن است پارامترهای پرس‌وجو داشته باشند.",
    "Export a backup first if you want to keep a copy.": "اگر می‌خواهید یک نسخه نگه دارید، ابتدا پشتیبان را صادر کنید.",
    "If a tab renderer crashes, Murky automatically restores that tab instead of leaving it blank.": "اگر رندرکننده زبانه از کار بیفتد، Murky زبانه را خودکار بازیابی می‌کند و آن را خالی نمی‌گذارد.",
    "Enabled": "فعال",
    "Microphone/camera access is denied to external websites. Murky's own voice features retain access.": "دسترسی میکروفون/دوربین برای وب‌سایت‌های خارجی رد شده است. قابلیت‌های صوتی خود Murky همچنان دسترسی دارند.",
    "Restricted": "محدود",
    "Blocks network requests from external websites. Murky internal pages and local features continue to work.": "درخواست‌های شبکه از وب‌سایت‌های خارجی را مسدود می‌کند. صفحات داخلی و قابلیت‌های محلی Murky همچنان کار می‌کنند.",
    "Saves a local backup of your settings, history and bookmarks before a purge.": "پیش از پاک‌سازی، یک پشتیبان محلی از تنظیمات، تاریخچه و نشانک‌های شما ذخیره می‌کند.",
    "Clears browsing history, bookmarks, cookies, local storage, service workers and cached web data in one action.": "تاریخچه مرور، نشانک‌ها، کوکی‌ها، ذخیره‌سازی محلی، service workerها و داده‌های وب ذخیره‌شده را با یک عمل پاک می‌کند.",
    "Version …": "نسخه …",
