    "Back online. Reconnecting…": "دوباره آنلاین شدید. در حال اتصال مجدد…",
    "Murky blocked this page to protect you. If you understand the risk, you can open it anyway. Anything you send to {site} may be visible to others.": "Murky برای محافظت از شما این صفحه را مسدود کرد. اگر خطر را می‌دانید، می‌توانید به هر حال آن را باز کنید. هر چیزی که به {site} بفرستید ممکن است برای دیگران قابل مشاهده باشد.",
