    "Access denied": "دسترسی ممنوع",
    "You don't have permission to view this page. You may need to sign in.": "اجازه دیدن این صفحه را ندارید. ممکن است لازم باشد وارد شوید.",
    "Too many requests": "درخواست‌های بیش از حد",
    "This site is asking you to slow down. Wait a bit and try again.": "این سایت از شما می‌خواهد سرعت را کم کنید. کمی صبر کنید و دوباره تلاش کنید.",
    "Server error": "خطای سرور",
    "Something went wrong on the site's end. Try again in a moment.": "مشکلی در سمت سایت پیش آمد. کمی بعد دوباره تلاش کنید.",
    "Couldn't open this page": "باز کردن این صفحه ممکن نشد",
    "The site refused to show this page.": "سایت از نمایش این صفحه خودداری کرد.",
    "You're offline": "آفلاین هستید",
    "Murky can't reach the internet. Check your connection and we'll reconnect when you're back.": "Murky نمی‌تواند به اینترنت دسترسی پیدا کند. اتصال خود را بررسی کنید؛ وقتی برگشتید دوباره متصل می‌شویم.",
    "Can't find this site": "این سایت پیدا نشد",
    "Murky couldn't find a server called {site}. Check the address for typos.": "Murky سروری با نام {site} پیدا نکرد. نشانی را از نظر اشتباه تایپی بررسی کنید.",
    "{site} refused to connect": "{site} اتصال را رد کرد",
    "The site might be down. Try again in a moment.": "ممکن است سایت از کار افتاده باشد. کمی بعد دوباره تلاش کنید.",
    "Took too long to respond": "پاسخ‌دهی بیش از حد طول کشید",
    "{site} didn't answer in time. Try again in a moment.": "{site} به موقع پاسخ نداد. کمی بعد دوباره تلاش کنید.",
    "Connection interrupted": "اتصال قطع شد",
    "The connection to {site} was dropped before the page finished loading.": "اتصال به {site} پیش از پایان بارگذاری صفحه قطع شد.",
    "This site isn't safe to open": "باز کردن این سایت امن نیست",
    "Murky couldn't verify that this site's connection is secure, so it blocked the page.": "Murky نتوانست امن بودن اتصال به این سایت را تأیید کند، بنابراین صفحه را مسدود کرد.",
    "The site's security certificate was issued for a different address.": "گواهی امنیتی سایت برای نشانی دیگری صادر شده است.",
    "The site's security certificate has expired or isn't valid yet. Check your device's date and time.": "گواهی امنیتی سایت منقضی شده یا هنوز معتبر نیست. تاریخ و ساعت دستگاه خود را بررسی کنید.",
    "The site's certificate was issued by an authority Murky doesn't trust.": "گواهی سایت را مرجعی صادر کرده که Murky به آن اعتماد ندارد.",
    "Blocked by Murky": "توسط Murky مسدود شد",
    "{site} was blocked by your ad and tracker protection.": "{site} توسط محافظت شما در برابر تبلیغات و ردیاب‌ها مسدود شد.",
    "Too many redirects": "تغییر مسیرهای بیش از حد",
    "{site} keeps sending Murky in circles. Clearing its cookies often helps.": "{site} مدام Murky را دور خودش می‌چرخاند. پاک کردن کوکی‌های آن اغلب کمک می‌کند.",
    "That address doesn't look right": "این نشانی درست به نظر نمی‌رسد",
    "Murky can't open this address. Check it for typos.": "Murky نمی‌تواند این نشانی را باز کند. آن را از نظر اشتباه تایپی بررسی کنید.",
    "Proxy problem": "مشکل پروکسی",
