    "That file doesn't exist or can't be opened.": "این فایل وجود ندارد یا باز نمی‌شود.",
    "Something went wrong": "مشکلی پیش آمد",
    "Murky couldn't load {site}. Try again in a moment.": "Murky نتوانست {site} را بارگذاری کند. کمی بعد دوباره تلاش کنید."
