    "Loading…": "Завантаження…",
    "Not checked yet": "Ще не перевірено",
    "Murky keeps a rolling local log of browser network requests so you can inspect what leaves the browser.": "Murky веде поточний локальний журнал мережевих запитів браузера, щоб ви могли перевірити, що залишає браузер.",
    "Exports the current local request log as JSON. URLs may contain query parameters.": "Експортує поточний локальний журнал запитів у JSON. URL можуть містити параметри запиту.",
    "Export a backup first if you want to keep a copy.": "Спочатку експортуйте резервну копію, якщо хочете зберегти копію.",
    "If a tab renderer crashes, Murky automatically restores that tab instead of leaving it blank.": "Якщо засіб відтворення вкладки аварійно завершує роботу, Murky автоматично відновлює вкладку, а не залишає її порожньою.",
    "Enabled": "Увімкнено",
    "Microphone/camera access is denied to external websites. Murky's own voice features retain access.": "Зовнішнім вебсайтам заборонено доступ до мікрофона/камери. Власні голосові функції Murky зберігають доступ.",
    "Restricted": "Обмежено",
    "Blocks network requests from external websites. Murky internal pages and local features continue to work.": "Блокує мережеві запити із зовнішніх вебсайтів. Внутрішні сторінки Murky та локальні функції продовжують працювати.",
    "Saves a local backup of your settings, history and bookmarks before a purge.": "Перед очищенням зберігає локальну резервну копію налаштувань, історії та закладок.",
    "Clears browsing history, bookmarks, cookies, local storage, service workers and cached web data in one action.": "Однією дією очищає історію перегляду, закладки, cookie, локальне сховище, service worker та кешовані вебдані.",
    "Version …": "Версія …",
