    "Murky blocked this page to protect you. If you understand the risk, you can open it anyway. Anything you send to {site} may be visible to others.": "Murky заблокував цю сторінку, щоб захистити вас. Якщо ви розумієте ризик, можете все одно її відкрити. Усе, що ви надсилаєте на {site}, можуть бачити інші.",
    "Press space or click to play": "Натисніть пробіл або клацніть, щоб грати",
    "Game over. Press space or click to retry": "Гру закінчено. Натисніть пробіл або клацніть, щоб спробувати знову",
    "this site": "цей сайт",
    "Page not found": "Сторінку не знайдено",
    "There's nothing at this address. It may have moved or been deleted.": "За цією адресою нічого немає. Можливо, її переміщено або видалено.",
    "Access denied": "Доступ заборонено",
    "You don't have permission to view this page. You may need to sign in.": "У вас немає дозволу переглядати цю сторінку. Можливо, потрібно увійти.",
    "Too many requests": "Забагато запитів",
    "This site is asking you to slow down. Wait a bit and try again.": "Цей сайт просить вас пригальмувати. Трохи зачекайте й повторіть спробу.",
    "Server error": "Помилка сервера",
    "Something went wrong on the site's end. Try again in a moment.": "На боці сайту щось пішло не так. Повторіть спробу за хвилину.",
    "Couldn't open this page": "Не вдалося відкрити цю сторінку",
    "The site refused to show this page.": "Сайт відмовився показувати цю сторінку.",
    "You're offline": "Ви офлайн",
    "Murky can't reach the internet. Check your connection and we'll reconnect when you're back.": "Murky не може під’єднатися до інтернету. Перевірте з’єднання — ми знову під’єднаємося, коли воно з’явиться.",
    "Can't find this site": "Не вдається знайти цей сайт",
    "Murky couldn't find a server called {site}. Check the address for typos.": "Murky не знайшов сервер з іменем {site}. Перевірте адресу на друкарські помилки.",
    "{site} refused to connect": "{site} відхилив з’єднання",
    "The site might be down. Try again in a moment.": "Можливо, сайт не працює. Повторіть спробу за хвилину.",
    "Took too long to respond": "Відповідь надходила надто довго",
    "{site} didn't answer in time. Try again in a moment.": "{site} не відповів вчасно. Повторіть спробу за хвилину.",
    "Connection interrupted": "З’єднання перервано",
    "The connection to {site} was dropped before the page finished loading.": "З’єднання з {site} розірвалося до завершення завантаження сторінки.",
    "This site isn't safe to open": "Відкривати цей сайт небезпечно",
    "Murky couldn't verify that this site's connection is secure, so it blocked the page.": "Murky не зміг переконатися, що з’єднання з цим сайтом захищене, тому заблокував сторінку.",
    "The site's security certificate was issued for a different address.": "Сертифікат безпеки сайту видано для іншої адреси.",
    "The site's security certificate has expired or isn't valid yet. Check your device's date and time.": "Термін дії сертифіката безпеки сайту минув або ще не настав. Перевірте дату й час на пристрої.",
    "The site's certificate was issued by an authority Murky doesn't trust.": "Сертифікат сайту видано центром, якому Murky не довіряє.",
    "Blocked by Murky": "Заблоковано Murky",
    "{site} was blocked by your ad and tracker protection.": "{site} заблоковано вашим захистом від реклами та трекерів.",
    "Too many redirects": "Забагато перенаправлень",
    "{site} keeps sending Murky in circles. Clearing its cookies often helps.": "{site} водить Murky по колу. Часто допомагає очищення cookie цього сайту.",
    "That address doesn't look right": "Адреса виглядає неправильно",
    "Murky can't open this address. Check it for typos.": "Murky не може відкрити цю адресу. Перевірте її на друкарські помилки.",
    "Proxy problem": "Проблема з проксі",
    "Murky couldn't connect through your proxy server.": "Murky не вдалося під’єднатися через ваш проксі-сервер.",
    "File not found": "Файл не знайдено",
