    "Preview": "プレビュー",
    "Clear": "消去",
    "Removes your saved history. Bookmarks are not affected.": "保存した履歴を削除します。ブックマークには影響しません。",
    "Blocks network requests from external websites. Murky internal pages and local features continue to work.": "外部サイトからのネットワーク要求をブロックします。Murky の内部ページとローカル機能は引き続き動作します。",
    "Clears browsing history, bookmarks, cookies, local storage, service workers and cached web data in one action.": "閲覧履歴、ブックマーク、Cookie、ローカルストレージ、service worker、キャッシュされたWebデータを一度に消去します。",
    "Saves a local backup of your settings, history and bookmarks before a purge.": "消去する前に設定、履歴、ブックマークのローカルバックアップを保存します。",
    "Exports the current local request log as JSON. URLs may contain query parameters.": "現在のローカルリクエストログをJSONとしてエクスポートします。URLにはクエリパラメータが含まれる場合があります。",
    "If a tab renderer crashes, Murky automatically restores that tab instead of leaving it blank.": "タブのレンダラーがクラッシュした場合、Murky は空白のままにせず自動的にタブを復元します。",
    "Murky keeps a rolling local log of browser network requests so you can inspect what leaves the browser.": "Murky はブラウザーから外部へ送信されたものを確認できるよう、ネットワーク要求のローカルログを継続的に保存します。",
    "Restores every Murky setting to its default value": "すべての Murky 設定を既定値に戻します",
    "Export a backup first if you want to keep a copy.": "コピーを残したい場合は、先にバックアップをエクスポートしてください。",
