    "Back online. Reconnecting…": "オンラインに復帰しました。再接続しています…",
    "Murky blocked this page to protect you. If you understand the risk, you can open it anyway. Anything you send to {site} may be visible to others.": "Murky はあなたを守るためにこのページをブロックしました。リスクを理解している場合は、そのまま開くこともできます。{site} に送信した内容は他の人に見られる可能性があります。",
    "Press space or click to play": "スペースキーまたはクリックでプレイ",
