    "this site": "このサイト",
    "Page not found": "ページが見つかりません",
    "There's nothing at this address. It may have moved or been deleted.": "このアドレスには何もありません。移動または削除された可能性があります。",
    "Access denied": "アクセスが拒否されました",
    "You don't have permission to view this page. You may need to sign in.": "このページを表示する権限がありません。サインインが必要な場合があります。",
    "Too many requests": "リクエストが多すぎます",
    "This site is asking you to slow down. Wait a bit and try again.": "このサイトからペースを落とすよう求められています。しばらく待ってからもう一度お試しください。",
    "Server error": "サーバーエラー",
    "Something went wrong on the site's end. Try again in a moment.": "サイト側で問題が発生しました。しばらくしてからもう一度お試しください。",
    "Couldn't open this page": "このページを開けませんでした",
    "The site refused to show this page.": "サイトがこのページの表示を拒否しました。",
    "You're offline": "オフラインです",
    "Murky can't reach the internet. Check your connection and we'll reconnect when you're back.": "Murky はインターネットに接続できません。接続を確認してください。復帰したら自動的に再接続します。",
    "Can't find this site": "このサイトが見つかりません",
    "Murky couldn't find a server called {site}. Check the address for typos.": "{site} という名前のサーバーが見つかりませんでした。アドレスに入力ミスがないか確認してください。",
    "{site} refused to connect": "{site} が接続を拒否しました",
    "The site might be down. Try again in a moment.": "サイトがダウンしている可能性があります。しばらくしてからもう一度お試しください。",
    "Took too long to respond": "応答に時間がかかりすぎました",
    "{site} didn't answer in time. Try again in a moment.": "{site} が時間内に応答しませんでした。しばらくしてからもう一度お試しください。",
    "Connection interrupted": "接続が中断されました",
    "The connection to {site} was dropped before the page finished loading.": "ページの読み込みが完了する前に {site} との接続が切断されました。",
    "This site isn't safe to open": "このサイトは安全ではありません",
    "Murky couldn't verify that this site's connection is secure, so it blocked the page.": "このサイトへの接続が安全であることを確認できなかったため、Murky はページをブロックしました。",
    "The site's security certificate was issued for a different address.": "このサイトのセキュリティ証明書は別のアドレス用に発行されています。",
    "The site's security certificate has expired or isn't valid yet. Check your device's date and time.": "このサイトのセキュリティ証明書は期限切れか、まだ有効ではありません。デバイスの日付と時刻を確認してください。",
    "The site's certificate was issued by an authority Murky doesn't trust.": "このサイトの証明書は、Murky が信頼していない機関によって発行されています。",
    "Blocked by Murky": "Murky によりブロックされました",
    "{site} was blocked by your ad and tracker protection.": "{site} は広告・トラッカー保護によりブロックされました。",
    "Too many redirects": "リダイレクトが多すぎます",
    "{site} keeps sending Murky in circles. Clearing its cookies often helps.": "{site} が Murky を堂々巡りさせています。このサイトのCookieを削除すると改善することがよくあります。",
    "That address doesn't look right": "このアドレスは正しくないようです",
    "Murky can't open this address. Check it for typos.": "Murky はこのアドレスを開けません。入力ミスがないか確認してください。",
    "Proxy problem": "プロキシの問題",
    "Murky couldn't connect through your proxy server.": "Murky はプロキシサーバー経由で接続できませんでした。",
