    "Saves a local backup of your settings, history and bookmarks before a purge.": "삭제 전에 설정, 기록 및 북마크의 로컬 백업을 저장합니다.",
    "Exports the current local request log as JSON. URLs may contain query parameters.": "현재 로컬 요청 로그를 JSON으로 내보냅니다. URL에는 쿼리 매개변수가 포함될 수 있습니다.",
